CREATE DEFINER=`root`@`localhost` FUNCTION `levenshtein` (`s1` VARCHAR(255), `s2` VARCHAR(255)) RETURNS INT(11) DETERMINISTIC BEGIN
  DECLARE s1_len, s2_len, i, j, c, c_temp, cost INT;
  DECLARE s1_char CHAR;
  DECLARE cv0, cv1 VARBINARY(256);

  SET s1_len = CHAR_LENGTH(s1);
  SET s2_len = CHAR_LENGTH(s2);
  SET cv1 = 0x00;
  SET j = 1;
  WHILE j <= s2_len DO
    SET cv1 = CONCAT(cv1, UNHEX(HEX(j)));
    SET j = j + 1;
  END WHILE;
  SET i = 1;
  WHILE i <= s1_len DO
    SET s1_char = SUBSTRING(s1, i, 1);
    SET c = i;
    SET cv0 = UNHEX(HEX(i));
    SET j = 1;
    WHILE j <= s2_len DO
      SET cost = IF(s1_char = SUBSTRING(s2, j, 1), 0, 1);
      SET c_temp = ORD(SUBSTRING(cv1, j, 1)) + 1;
      SET c = IF(c > c_temp, c_temp, c);
      SET c_temp = ORD(SUBSTRING(cv1, j - 1, 1)) + cost;
      SET c = IF(c > c_temp, c_temp, c);
      SET cv0 = CONCAT(cv0, UNHEX(HEX(c)));
      SET j = j + 1;
    END WHILE;
    SET cv1 = cv0;
    SET i = i + 1;
  END WHILE;
  RETURN c;
END$$

